#!/usr/bin/env python3
"""PLOS ONE versions of Figs 1-4, generated by the unchanged v22 figure functions (make_figures_v22.py).

Only presentation changes for the PLOS figure requirements (journals.plos.org/plosone/s/figures, read 2026-11-04):
  * font Arial (v22: DejaVu Sans); every text element at least 8 pt (v22: 6.0-8 pt)
  * figure canvas enlarged so that the larger text fits; final width <= 7.5 in, height <= 8.75 in
  * TIFF, RGB 8 bit/channel, no alpha, LZW, 300 dpi; a vector PDF is also written for checking
No data are read or computed differently: the plotted values come from the same functions and stored outputs.

Usage (project root):  python revizyon_v22/manuscript/v40_plos_work/scripts/make_figures_plos.py
Writes revizyon_v22/manuscript/v40_plos_work/SUBMISSION_FILES/Fig{1..4}.tif and INTERNAL_CHECKS/figures_pdf/Fig{1..4}.pdf
"""
from __future__ import annotations

import sys
from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
from matplotlib.text import Text  # noqa: E402
from PIL import Image  # noqa: E402

HERE = Path(__file__).resolve().parent
WORK = HERE.parent
sys.path.insert(0, str(WORK.parent))  # revizyon_v22/manuscript
import make_figures_v22 as F  # noqa: E402

MIN_PT = 8.0
DPI = 300
# canvas scale per figure (width, height), chosen so that 8-pt text fits the v22 layout
SCALE = {"Fig1": (1.23, 1.42), "Fig2": (1.0, 1.25), "Fig3": (1.0, 1.25), "Fig4": (1.0, 1.15)}
OUT_TIF = WORK / "SUBMISSION_FILES"
OUT_PDF = WORK / "INTERNAL_CHECKS" / "figures_pdf"

plt.rcParams.update({"font.family": "Arial", "mathtext.fontset": "custom", "mathtext.rm": "Arial",
                     "mathtext.it": "Arial:italic", "pdf.fonttype": 42})

_current = {"name": None}
_orig_subplots = plt.subplots


def _subplots(*a, **k):
    sx, sy = SCALE[_current["name"]]
    w, h = k.get("figsize", plt.rcParams["figure.figsize"])
    k["figsize"] = (w * sx, h * sy)
    return _orig_subplots(*a, **k)


# v40 (review MK-PLOSONE-20261104-01): panel titles name the tuned contrasts (Fig 2); panel letters (Fig 3)
FIG2_TITLES = {"(a) Distillation −\nuniform smoothing": "(a) Tuned distillation −\ntuned uniform smoothing",
               "(b) Distillation −\nentropy-matched smoothing": "(b) Tuned distillation −\ntuned entropy-matched",
               "(c) Distillation −\nhard labels": "(c) Tuned distillation −\nhard labels"}


def _relabel(fig, name):
    axes = [ax for ax in fig.axes if ax.get_title(loc="left")]
    if name == "Fig2":
        for ax in axes:
            old = ax.get_title(loc="left")
            ax.set_title(FIG2_TITLES[old], loc="left", fontsize=MIN_PT)
        assert len(axes) == 3
    if name == "Fig3":
        for letter, ax in zip("abcde", axes):
            ax.set_title(f"({letter}) {ax.get_title(loc='left')}", loc="left", fontsize=MIN_PT)
        assert len(axes) == 5


def _save(fig, name):
    _relabel(fig, name)
    for t in fig.findobj(Text):
        if t.get_text() and t.get_fontsize() < MIN_PT:
            t.set_fontsize(MIN_PT)
    if name == "Fig3":
        fig.tight_layout(h_pad=1.2, w_pad=1.0)
    OUT_PDF.mkdir(parents=True, exist_ok=True); OUT_TIF.mkdir(parents=True, exist_ok=True)
    fig.savefig(OUT_PDF / f"{name}.pdf", bbox_inches="tight", pad_inches=0.03)
    png = OUT_PDF / f"{name}_300dpi.png"
    fig.savefig(png, dpi=DPI, bbox_inches="tight", pad_inches=0.03, facecolor="white")
    plt.close(fig)
    im = Image.open(png).convert("RGB")
    w_in, h_in = im.width / DPI, im.height / DPI
    assert 2.63 <= w_in <= 7.5 and h_in <= 8.75, (name, w_in, h_in)
    im.save(OUT_TIF / f"{name}.tif", compression="tiff_lzw", dpi=(DPI, DPI))
    png.unlink()
    print(f"{name}.tif  {im.width} x {im.height} px  ({w_in:.2f} x {h_in:.2f} in at {DPI} dpi)")


plt.subplots = _subplots
F.plt.subplots = _subplots
F.save = _save

for fn in ("fig1", "fig2", "fig3", "fig4"):
    _current["name"] = "Fig" + fn[-1]
    getattr(F, fn)()
